import { NextResponse } from 'next/server'
import { z } from 'zod'
import { activityFeedQuery, type ActivityFeedRow } from '@/lib/activityFeed'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { getAuthUser } from '@/lib/auth/session'
import { validateBody, activitySchema } from '@/lib/validation/apiValidation'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface UserActivityRow {
  id: string
  project_id: string | null
  activity_type: string
  entity_type: string | null
  entity_id: string | null
  description: string
  metadata: unknown | null
  created_at: Date
}

export const dynamic = 'force-dynamic'

/**
 * GET /api/activity
 *
 * Returns personal entries and project records/audit events within current read access.
 * Query params:
 *   - project_id: filter by project
 *   - limit: max results (default 20, max 50)
 *   - offset: pagination offset
 */
export const GET = apiHandler(
  { auth: true, rateLimit: { max: 120, windowMs: 60000 } },
  async (req, ctx) => {
    const url = new URL(req.url)
    const parsed = z.object({
      project_id: z.string().uuid().nullable(),
      limit: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(1).max(50)),
      offset: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(0).max(100_000)),
    }).safeParse({
      project_id: url.searchParams.get('project_id'),
      limit: url.searchParams.get('limit') ?? '20',
      offset: url.searchParams.get('offset') ?? '0',
    })
    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid activity filters', code: 'VALIDATION_ERROR' }, { status: 400 })
    }
    const { project_id: projectId, limit, offset } = parsed.data
    const result = await db.query<ActivityFeedRow>(
      activityFeedQuery, [ctx.userId, limit + 1, offset, projectId],
    )
    const activities = result.rows.slice(0, limit)
    return apiSuccess({
      activities,
      pagination: { limit, offset, total: activities.length, hasMore: result.rows.length > limit },
    })
  },
)

/**
 * POST /api/activity
 * Log a user activity (called internally by other actions).
 * Body: { activityType, description, projectId?, entityType?, entityId?, metadata? }
 */
export const POST = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const user = await getAuthUser()
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = validateBody(ctx.body, activitySchema)
    const activityType = body.activityType
    const description = String(body.description || '')

    if (!activityType || !description) {
      return NextResponse.json(
        { error: 'activityType and description are required' },
        { status: 400 },
      )
    }

    const result = await db.query<UserActivityRow>(
      `INSERT INTO user_activity (user_id, project_id, activity_type, entity_type, entity_id, description, metadata)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING id, created_at`,
      [
        user.id,
        body.projectId || null,
        activityType,
        body.entityType || null,
        body.entityId || null,
        description,
        JSON.stringify(body.metadata || {}),
      ],
    )

    return apiSuccess({
      id: result.rows[0].id,
      createdAt: result.rows[0].created_at,
    })
  },
)
